<?php defined('ABSPATH')||exit;$filters=\RadmanLibrary\Catalog\filters(); ?>
<section class="rdl-prd-arc rdc-ctr rdc-main"><header><h1><?php if(is_tax(array_keys(\RadmanLibrary\Catalog\TAX)))single_term_title();else echo 'کاتالوگ محصولات'; ?></h1><p>معرفی محصولات، تصاویر و مشخصات؛ بدون فروش آنلاین.</p></header>
<div class="rdl-prd-layout"><aside class="rdl-prd-sb" aria-label="جستجو و دسته‌بندی محصولات"><form class="rdc-srch" role="search" action="<?php echo esc_url(\RadmanLibrary\Catalog\url()); ?>" method="get"><label class="rdl-prd-sr" for="rdl-prd-srch">جستجوی محصول</label><input id="rdl-prd-srch" name="rm_search" type="search" placeholder="جستجوی محصول…" value="<?php echo esc_attr($filters['rm_search']); ?>"><button aria-label="جستجو" type="submit"><?php echo \RadmanCT\icon('search'); ?></button></form>
<p><a href="<?php echo esc_url(\RadmanLibrary\Catalog\url()); ?>">همهٔ محصولات</a></p>
<?php foreach(\RadmanLibrary\Catalog\TAX as $tax=>$label):$terms=get_terms(['taxonomy'=>$tax,'hide_empty'=>true]);if(is_wp_error($terms)||!$terms)continue; ?><section><h2><?php echo esc_html($label); ?></h2><?php if($tax==='radman_product_cat'){$term=get_queried_object();\RadmanCT\UI\category_tree($terms,['current'=>$term instanceof WP_Term&&$term->taxonomy===$tax?$term->term_id:0,'ancestors'=>$term instanceof WP_Term&&$term->taxonomy===$tax?get_ancestors($term->term_id,$tax):[],'url'=>static fn($term)=>get_term_link($term)]);}else{echo '<ul>';foreach($terms as $term)echo '<li><a href="'.esc_url(get_term_link($term)).'">'.esc_html($term->name).'</a></li>';echo '</ul>';} ?></section><?php endforeach; ?></aside>
<div><div class="rdl-prd-grid"><?php if(have_posts()):while(have_posts()):the_post();\RadmanLibrary\Catalog\card(get_post());endwhile;else: ?><p>محصولی پیدا نشد.</p><?php endif; ?></div><?php the_posts_pagination(['prev_text'=>'قبلی','next_text'=>'بعدی']); ?></div></div></section>
